from pathlib import Path
import json,shutil,os
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parents[1];base=os.environ.get('CAMPUS_TEST_URL','http://127.0.0.1:8129/')
hook="""window.__eight={test:async()=>{const {accessStairs,stairBands,stairSurface}=await import('./stair-layout.js'),defs=accessStairs(campus,terrain,roadNetwork).filter(s=>s.id.startsWith('zhili-')),result={failures:[],walk:0,rays:0,seams:0,terrain:[]};scene.updateMatrixWorld(true);for(const s of defs){if(s.steps!==8)result.failures.push('steps');const [a,b]=s.line,dx=b[0]-a[0],dz=b[1]-a[1],l=Math.hypot(dx,dz),nx=-dz/l,nz=dx/l;const at=(u,v)=>[a[0]+dx*u+nx*v,a[1]+dz*u+nz*v];for(const fraction of [-.4,0,.4])for(const reverse of [false,true]){const start=at(reverse?1:0,s.width*fraction);motion.riding=false;player.position.set(start[0],stairSurface(s,reverse?1:0,...start)+.08,start[1]);for(let i=1;i<=160;i++){const u=reverse?1-i/160:i/160,p=at(u,s.width*fraction);if(!movePlayer(p[0]-player.position.x,p[1]-player.position.z,.3))result.failures.push({kind:'stairs-blocked',id:s.id,i,fraction,reverse});if(Math.abs(player.position.y-stairSurface(s,u,...p)-.08)>.001)result.failures.push({kind:'support',id:s.id,i});result.walk++;}}const mesh=scene.getObjectByName(s.id+'-staircase');for(const band of stairBands(s))for(const fraction of [-.45,-.2,0,.2,.45]){const u=(band.start+band.end)/2,p=at(u,s.width*fraction),ray=new THREE.Raycaster(new THREE.Vector3(p[0],s.top+5,p[1]),new THREE.Vector3(0,-1,0)),hit=ray.intersectObject(mesh)[0];if(!hit||Math.abs(hit.point.y-stairSurface(s,u,...p))>.0001)result.failures.push({kind:'ray',id:s.id,fraction,error:hit?.point.y-stairSurface(s,u,...p)});result.rays++;}if(s.bottomAt)for(let i=1;i<48;i++){const p=at(1,s.width*(i/48-.5)),x=p[0]+dx/l*.001,z=p[1]+dz/l*.001,h=siteDetails.sidewalkAt(x,z);if(h===null||Math.abs(h-s.bottomAt(...p))>.001)result.failures.push({kind:'seam',i,h,bottom:s.bottomAt(...p)});result.seams++;}}
const access=campus.teachingAccess,at=(u,v)=>access.anchor.map((a,i)=>a+access.outward[i]*u+access.along[i]*v);for(const riding of [false,true])for(const reverse of [false,true]){const start=at(1.7,reverse?11.4:.8);motion.riding=riding;player.position.set(start[0],siteDetails.sidewalkAt(...start),start[1]);for(let i=1;i<=220;i++){const p=at(1.7,reverse?11.4-10.6*i/220:.8+10.6*i/220);if(!movePlayer(p[0]-player.position.x,p[1]-player.position.z,riding?.65:.3))result.failures.push({kind:'walkway-blocked',i,riding,reverse});if(Math.abs(player.position.y-siteDetails.sidewalkAt(...p))>.001)result.failures.push({kind:'walkway-support',i});result.walk++;}}const under=at(-4.2,6);if(!siteDetails.blocked(under[0],under[1],.3,roadNetwork.surfaceHeight(...under)+1))result.failures.push('landing-foundation-collision');for(let v=1;v<12;v+=1){const p=at(.2,v),ground=terrainHeight(...p),tile=siteDetails.sidewalkAt(...p);result.terrain.push({v,ground,tile});if(ground>tile+.002)result.failures.push({kind:'terrain-through-pavement',v,ground,tile});}return result;},view:mode=>{window.__freeze=true;const a=campus.teachingAccess,p=a.anchor,n=a.outward,t=a.along,base=terrain.platformHeight(campus.places.find(b=>b.osm===campus.levelLink.from));if(mode==='air'){cam.position.set(p[0]+n[0]*27,base+42,p[1]+n[1]*27);cam.lookAt(p[0]-n[0]*10+t[0]*6,base-2,p[1]-n[1]*10+t[1]*6);}else{cam.position.set(p[0]+n[0]*13+t[0]*7,base+1,p[1]+n[1]*13+t[1]*7);cam.lookAt(p[0]-n[0]*15+t[0]*5,base+1,p[1]-n[1]*15+t[1]*5);}}};let previous=performance.now();"""
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=shutil.which('chromium'),args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 for mobile in ([False] if os.environ.get('CAMPUS_DESKTOP_ONLY') else [False,True]):
  c=b.new_context(viewport={'width':390,'height':844} if mobile else {'width':1100,'height':850},has_touch=mobile,is_mobile=mobile);c.route('https://cdn.jsdelivr.net/npm/three@0.160.1/build/three.module.js',lambda r:r.fulfill(path='/tmp/three.module.js',content_type='text/javascript'));c.route('https://api.github.com/**',lambda r:r.fulfill(json=[]))
  html=(root/'index.html').read_text().replace('let previous=performance.now();',hook).replace('cam.position.lerp(target,','if(!window.__freeze)cam.position.lerp(target,').replace('else cam.lookAt(player.position.x,player.position.y+1.1,player.position.z);','else if(!window.__freeze)cam.lookAt(player.position.x,player.position.y+1.1,player.position.z);');c.route(base,lambda r:r.fulfill(body=html,content_type='text/html'))
  page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base);page.wait_for_function('window.__eight',timeout=120000);page.get_by_role('button',name='開始探索',exact=True).click(timeout=90000)
  result=page.evaluate('__eight.test()');print(json.dumps({'mobile':mobile,**result}),flush=True);assert not result['failures'],result
  for mode in ['air','ground']:
   page.evaluate('(m)=>__eight.view(m)',mode);page.wait_for_timeout(300);page.screenshot(path=f'/tmp/nknu-eight-{mobile}-{mode}.png')
  badge=page.locator('#tools .campus-beta');assert badge.inner_text()=='測試版'
  assert page.locator('#tools').evaluate('(tools)=>tools.scrollWidth<=tools.clientWidth+1')
  if mobile:
   page.set_viewport_size({'width':844,'height':390});assert page.locator('#tools').evaluate('(tools)=>tools.scrollWidth<=tools.clientWidth+1');page.set_viewport_size({'width':390,'height':844})
  page.locator('#tools').get_by_role('link',name='和平校區 測試版').click();page.get_by_role('button',name='開始探索',exact=True).click(timeout=90000);assert page.locator('#top .campus-beta').inner_text()=='測試版';page.screenshot(path=f'/tmp/nknu-eight-heping-{mobile}.png');assert not errors,errors;c.close()
 b.close();print('PASS: eight-step full-width traversal/render/support, restored walk/ride route, terrain clearance, beta badge and campus switching')
